// Recebe a resposta do cérebro e monta o POST pro webhook de entrada (Incoming Webhook) da sala no Google Chat.
// Cadastre aqui cada sala: id da sala (meta.space, ex. 'spaces/AAAAxxxx') ou nome → URL do webhook de entrada.
// (Google Chat > sala > Apps e integrações > Webhooks > Adicionar.)
const WEBHOOKS = {
  // 'spaces/AAAAxxxxxxx': 'https://chat.googleapis.com/v1/spaces/AAAAxxxxxxx/messages?key=...&token=...',
  // 'Comercial': 'https://chat.googleapis.com/v1/spaces/.../messages?key=...&token=...',
};
const saida = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const meta = b.meta || {};
  let url = WEBHOOKS[meta.space] || WEBHOOKS[meta.spaceNome] || '';
  if (!url) { throw new Error(`Sem webhook cadastrado pra sala ${meta.spaceNome || meta.space}. Edite o nó "Monta envio".`); }
  // responde na mesma thread; se a sala não tiver threads, cai pra mensagem nova
  url += (url.includes('?') ? '&' : '?') + 'messageReplyOption=REPLY_MESSAGE_FALLBACK_TO_NEW_THREAD';
  const corpo = { text: String(b.texto || '').slice(0, 4000) };
  if (meta.thread) corpo.thread = { name: meta.thread };
  saida.push({ json: { url, corpo } });
}
return saida;
